import re
from datetime import datetime, timedelta

def parse_ics(path):
    events = []
    with open(path) as f:
        content = f.read()
    for m in re.finditer(r'BEGIN:VEVENT(.*?)END:VEVENT', content, re.S):
        block = m.group(1)
        start = re.search(r'DTSTART:(\d{8}T\d{6}Z)', block).group(1)
        end = re.search(r'DTEND:(\d{8}T\d{6}Z)', block).group(1)
        events.append((datetime.strptime(start, '%Y%m%dT%H%M%SZ'), datetime.strptime(end, '%Y%m%dT%H%M%SZ')))
    return events

